#!/usr/bin/env python3
"""Print the next order id.

Ids look like ORD- followed by four base36 characters.  The next id is the
successor of the most recent id in ids.txt (read from the current directory).
"""

import sys
from pathlib import Path


def parse(code):
    return int(code, 36)


def format_code(value):
    code = ""
    for _ in range(4):
        code = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[value % 36] + code
        value //= 36
    return code


def main():
    ids_path = Path("ids.txt")
    lines = [line.strip() for line in ids_path.read_text().splitlines() if line.strip()]
    if not lines:
        raise SystemExit("ids.txt is empty")
    last = lines[-1]
    if not last.startswith("ORD-") or len(last) != 8:
        raise SystemExit(f"unexpected id: {last!r}")
    code = last[4:]
    value = parse(code)
    print(f"ORD-{format_code((value + 1) % (36 ** 4))}")


if __name__ == "__main__":
    main()

