#!/usr/bin/env python3
"""Print the next order id after the most recent one in ids.txt."""

import sys

def to_base36(n: int, width: int = 4) -> str:
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n < 0:
        raise ValueError("id suffix out of range")
    s = ""
    while n > 0:
        n, rem = divmod(n, 36)
        s = chars[rem] + s
    return s.rjust(width, "0")

def from_base36(s: str) -> int:
    return int(s, 36)

def main() -> None:
    try:
        with open("ids.txt", "r") as f:
            lines = [ln.strip() for ln in f if ln.strip()]
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last = lines[-1]
    if not last.startswith("ORD-") or len(last) != 8:
        print(f"invalid id: {last}", file=sys.stderr)
        sys.exit(1)

    suffix = last[4:]
    try:
        nxt = from_base36(suffix) + 1
    except ValueError:
        print(f"invalid id suffix: {suffix}", file=sys.stderr)
        sys.exit(1)

    print(f"ORD-{to_base36(nxt)}")

if __name__ == "__main__":
    main()
