#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int) -> str:
    """Convert an integer to a base-36 string."""
    if n == 0:
        return '0'
    result = []
    while n > 0:
        result.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(result))


def main() -> None:
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('Error: ids.txt not found', file=sys.stderr)
        sys.exit(1)

    if not lines:
        print('Error: ids.txt is empty', file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]

    if not last_id.startswith('ORD-') or len(last_id) != 8:
        print(f'Error: unexpected id format: {last_id}', file=sys.stderr)
        sys.exit(1)

    code = last_id[4:]  # The 4-character base-36 code

    try:
        value = int(code, 36)
    except ValueError:
        print(f'Error: could not parse code: {code}', file=sys.stderr)
        sys.exit(1)

    next_code = to_base36(value + 1).zfill(4).upper()
    print(f'ORD-{next_code}')


if __name__ == '__main__':
    main()

