#!/usr/bin/env python3
"""Generate the next order id.

Reads ids.txt (one order id per line, most recent last) from the current
directory and prints the next id to stdout followed by a newline. Ids have
the form ORD- followed by four base36 characters.
"""
import sys

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    return int(s, 36)


def to_base36(n: int, width: int) -> str:
    """Convert an integer to a zero-padded base36 string of the given width."""
    if n == 0:
        return DIGITS[0] * width
    chars = []
    while n:
        n, rem = divmod(n, len(DIGITS))
        chars.append(DIGITS[rem])
    return "".join(reversed(chars)).rjust(width, DIGITS[0])


def load_last_id(path: str = "ids.txt") -> str:
    """Return the most recent order id from the file."""
    with open(path, encoding="utf-8") as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        raise ValueError(f"{path} contains no order ids")
    return lines[-1]


def next_id(last_id: str) -> str:
    """Return the id that follows the given id (one more than the sequential code)."""
    prefix, suffix = last_id.rsplit("-", 1)
    n = from_base36(suffix) + 1
    return f"{prefix}-{to_base36(n, len(suffix))}"


def main() -> None:
    try:
        last = load_last_id()
    except OSError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(next_id(last))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
