#!/usr/bin/env python3

import sys

ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
BASE = len(ALPHABET)

def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    n = 0
    for c in s:
        n = n * BASE + ALPHABET.index(c)
    return n

def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer to a base-36 string padded to the given width."""
    chars = []
    for _ in range(width):
        chars.append(ALPHABET[n % BASE])
        n //= BASE
    return ''.join(reversed(chars))

def main():
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('Error: ids.txt not found', file=sys.stderr)
        sys.exit(1)

    if not lines:
        print('ORD-0000')
        return

    last_id = lines[-1]
    if not last_id.startswith('ORD-') or len(last_id) != 8:
        print(f'Error: invalid id format: {last_id}', file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    try:
        num = base36_decode(suffix)
    except (ValueError, IndexError):
        print(f'Error: invalid base-36 suffix: {suffix}', file=sys.stderr)
        sys.exit(1)

    next_num = num + 1
    next_suffix = base36_encode(next_num, width=4)
    print(f'ORD-{next_suffix}')

if __name__ == '__main__':
    main()

