"""Merge all CSV files under data/ into all.csv."""

import os
import sys
import csv

DATA_DIR = "data"
OUTPUT_FILE = "all.csv"


def main():
    # Gather all .csv files sorted
    csv_files = sorted(
        fname
        for fname in os.listdir(DATA_DIR)
        if fname.endswith(".csv")
    )

    if not csv_files:
        print("No CSV files found in data/.", file=sys.stderr)
        sys.exit(1)

    with open(OUTPUT_FILE, "w", newline="") as out:
        writer = csv.writer(out)
        written_header = False

        for fname in csv_files:
            path = os.path.join(DATA_DIR, fname)
            with open(path, newline="") as f:
                reader = csv.reader(f)
                for i, row in enumerate(reader):
                    if i == 0:
                        # Header row — write only once
                        if not written_header:
                            writer.writerow(row)
                            written_header = True
                    else:
                        writer.writerow(row)

    print(f"Merged {len(csv_files)} files into {OUTPUT_FILE}.")


if __name__ == "__main__":
    main()

