#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"


def sha256_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    manifest = {}
    # Scan release/ recursively, collecting only files (not directories).
    for p in sorted(RELEASE_DIR.rglob("*")):
        if p.is_file():
            # Store the path relative to the release directory.
            manifest[str(p.relative_to(RELEASE_DIR))] = sha256_digest(p)

    out = Path(__file__).resolve().parent / "manifest.json"
    out.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(f"Wrote manifest.json with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

