#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def compute_sha256(filepath: Path) -> str:
    """Return the SHA-256 hex digest of the file at *filepath*."""
    hasher = hashlib.sha256()
    with filepath.open("rb") as f:
        while True:
            block = f.read(65536)
            if not block:
                break
            hasher.update(block)
    return hasher.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    # Walk release/ recursively, collecting every regular file.
    for path in RELEASE_DIR.rglob("*"):
        if path.is_file():
            # Store path relative to repository root, using forward slashes.
            rel = str(path.relative_to(RELEASE_DIR.parent)).replace("\\", "/")
            manifest[rel] = compute_sha256(path)

    # Write sorted for deterministic output.
    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")


if __name__ == "__main__":
    main()

