#!/usr/bin/env python3
"""Write manifest.json in the repository root.

The manifest is a JSON object with one entry per file under release/,
mapping each file's path (relative to release/) to its SHA-256 hex digest.
"""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def sha256_hex(file_path: Path) -> str:
    digest = hashlib.sha256()
    with file_path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def build_manifest() -> dict[str, str]:
    manifest: dict[str, str] = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel = path.relative_to(RELEASE_DIR).as_posix()
            manifest[rel] = sha256_hex(path)
    return manifest


def main() -> None:
    if not RELEASE_DIR.is_dir():
        raise SystemExit(f"error: {RELEASE_DIR} is not a directory")
    manifest = build_manifest()
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()
