#!/usr/bin/env python3
"""Print report file names under reports/ in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_key(name):
    """Extract the numeric part from a report filename for sorting."""
    m = re.search(r"report-(\d+)\.txt$", name)
    return int(m.group(1)) if m else float("inf")


def main():
    try:
        files = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    reports = [f for f in files if re.match(r"report-\d+\.txt$", f)]
    reports.sort(key=report_key)

    for name in reports:
        print(name)


if __name__ == "__main__":
    main()

