#!/usr/bin/env python3
"""List the file names under reports/ in report order (numeric order of the suffix)."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")


def report_sort_key(filename: str) -> tuple:
    """Return a sort key that orders reports by their trailing numeric suffix."""
    m = re.search(r"(\d+)", filename)
    # If no number is found, push it to the end.
    return (int(m.group(1)) if m else float("inf"), filename)


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"Error: directory '{REPORTS_DIR}' not found.", file=__import__("sys").stderr)
        __import__("sys").exit(1)

    # Only consider regular files, skip hidden files.
    files = [e for e in entries if not e.startswith(".")]
    files.sort(key=report_sort_key)

    for fname in files:
        print(fname)


if __name__ == "__main__":
