import sys
from datetime import datetime, timezone

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
DAYS_OLD = 7
SECONDS_PER_DAY = 86400


def parse_timestamp(line: str) -> int | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' from the start of a line and return Unix timestamp."""
    try:
        ts_str = line[:19]
        dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
        return int(dt.replace(tzinfo=timezone.utc).timestamp())
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - DAYS_OLD * SECONDS_PER_DAY

    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {LOG_FILE} not found.", file=sys.stderr)
        sys.exit(1)

    keep_lines: list[str] = []
    archive_lines: list[str] = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            archive_lines.append(line)
        else:
            keep_lines.append(line)

    with open(LOG_FILE, "w") as f:
        f.writelines(keep_lines)

    if archive_lines:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive_lines)


if __name__ == "__main__":
    main()

