"""Rotate app.log: move entries older than 7 days before AS_OF to archive.log."""

import datetime
import sys


def parse_timestamp(line: str) -> datetime.datetime | None:
    """Parse the leading YYYY-MM-DD HH:MM:SS from a log line."""
    if len(line) < 19 or line[4] != '-' or line[7] != '-' or line[10] != ' ' or line[13] != ':' or line[16] != ':':
        return None
    try:
        return datetime.datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff_dt = datetime.datetime.fromtimestamp(as_of, tz=datetime.timezone.utc) - datetime.timedelta(days=7)

    all_entries: list[tuple[datetime.datetime, str]] = []

    with open('app.log', 'r') as f:
        for line in f:
            line = line.rstrip('\n')
            dt = parse_timestamp(line)
            if dt is None:
                # Keep lines that can't be parsed (add to both lists maybe).
                # Assume they stay in app.log with a sentinel past the cutoff.
                all_entries.append((cutoff_dt, line))
            else:
                # Make the parsed datetime timezone-aware (naive from strptime).
                dt = dt.replace(tzinfo=datetime.timezone.utc)
                all_entries.append((dt, line))

    old_entries: list[str] = []
    new_entries: list[str] = []

    for dt, line in all_entries:
        if dt < cutoff_dt:
            old_entries.append(line)
        else:
            new_entries.append(line)

    # Append old entries to archive.log
    if old_entries:
        with open('archive.log', 'a') as f:
            for entry in old_entries:
                f.write(entry + '\n')

    # Rewrite app.log with remaining entries
    with open('app.log', 'w') as f:
        for entry in new_entries:
            f.write(entry + '\n')


if __name__ == '__main__':
    main()
